+                : 'No stale phase labels to remove';
+          
+            return {
+              phase_label_set: true,
+              phase_label_name: label,
+              stale_labels_removed: removed,
+              reason: `Set phase label ${label}. ${removalMsg}`,
+            };
+          }
+          
+          if (typeof module !== 'undefined') {
+            module.exports = { setPhaseLabel };
+          }
